{
  "critique": [
    {
      "design": "r0A",
      "good": "错误码和英文错误信息完整且便于纵向扫描；含义列大致落在首屏内，读者可以看到问题标识及部分解释。",
      "problems": "含义列文字被挤成短行，access_token 被拆开；解决办法完全位于首屏之外，较窄的说明列也使各行很高，标识列出现大片空白。",
      "cause": "含义列 114px 仅有 93px 内容宽度，小于最长不可拆词的 95px；解决办法列 210px 面对长段落仍偏窄，决定了多数行的高度。前两列合计 245px，使解决办法从视口右缘之外开始。"
    },
    {
      "design": "r0B",
      "good": "所有技术词和错误标识符保持完整；含义和解决办法的行长更舒适，行高明显降低，横向阅读说明更顺畅。",
      "problems": "首屏只能看到含义列的一部分，解决办法需横向滚动才能阅读；总宽度较大，阅读末列时问题标识会离开视口，回查行信息有成本。",
      "cause": "前两列合计 245px，含义列又占 160px，因此解决办法从约 405px 处开始；260px 的解决办法列改善了长文本排版，但也增加了横向滚动距离。"
    },
    {
      "design": "r0C",
      "good": "全表落在首屏宽度内，四列关系和解决办法均可立即看到，无需横向滚动。",
      "problems": "英文错误标识符及技术词被频繁拆断，中文说明也挤成极短行；解决办法高达 24 行，整表过长，空白标识列使行内信息显得分离，跨行比较困难。",
      "cause": "错误信息列 100px、含义列 75px 和解决办法列 114px 的内容宽度分别只有 79px、54px 和 93px，均小于各自最长不可拆词的宽度；尤其解决办法列过窄，拉高了整行。"
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "均衡阅读",
      "widths": [70, 175, 140, 260],
      "change": "以 r0B 为基础，将含义列收窄 20px；仍为最长技术词保留足够空间，让解决办法更靠近首屏，同时保留较舒适的说明行长。"
    },
    {
      "name": "紧凑滚动",
      "widths": [70, 175, 116, 230],
      "change": "将含义列设为容纳最长不可拆词的最小宽度，解决办法列比 r0A 加宽；减少总滚动距离，同时修复 access_token 拆字并缓解长解决办法造成的高行。"
    },
    {
      "name": "长说明优先",
      "widths": [70, 175, 125, 300],
      "change": "给最长的解决办法更多宽度，以降低行高并改善段落阅读；含义列仍可容纳技术词，代价是需要更多横向滚动。"
    }
  ]
}
